<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import PageMeta from '@/Components/PageMeta.vue';import EmptyState from '@/Components/EmptyState.vue';import Pagination from '@/Components/Pagination.vue';import { hondurasDateTime } from '@/Composables/hondurasDate';import type {Paginated} from '@/types';type Log={id:string;action:string;field?:string;created_at:string;medical_document_id?:string;document?:{public_code?:string;original_filename?:string}|null;metadata?:unknown};defineProps<{logs:Paginated<Log>}>();const date=(v:string)=>hondurasDateTime(v);</script>
<template><AdminLayout title="Auditoría" eyebrow="Trazabilidad"><PageMeta title="Auditoría documental" noindex/><section class="admin-content"><div class="content-toolbar"><div><p class="kicker">Registro inmutable</p><h2>{{ logs.total }} eventos</h2></div><span class="privacy-chip">Trazabilidad</span></div><div class="panel"><div v-if="logs.data.length" class="audit-list"><article v-for="log in logs.data" :key="log.id"><span class="audit-dot"></span><div><strong>{{ log.action.replaceAll('_',' ') }}</strong><p>{{ log.document?.public_code||log.document?.original_filename||'Documento no disponible' }}<span v-if="log.field"> · {{ log.field }}</span></p></div><time>{{ date(log.created_at) }}</time></article></div><EmptyState v-else title="No hay eventos de auditoría"/><Pagination :links="logs.links"/></div></section></AdminLayout></template>
